import {
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  input,
  model,
  output,
} from "@angular/core";
import { lucideCheck, lucideTriangleAlert } from "@ng-icons/lucide";
import { KoButton } from "@/ui/primitives/button.component";
import {
  KoDialog,
  KoDialogContent,
  KoDialogDescription,
  KoDialogHeader,
  KoDialogTitle,
} from "@/ui/primitives/dialog.component";

/**
 * A confirm step. `[(open)]` closes it on Cancel, Escape and a backdrop click (the last two are ignored while `pending`); `(confirm)` leaves
 * closing to the caller, so the dialog can stay up with `pending` while the work runs. Extra body
 * content goes between the description and the buttons.
 */
@Component({
  selector: "ko-confirm-dialog",
  imports: [
    KoDialog,
    KoDialogContent,
    KoDialogHeader,
    KoDialogTitle,
    KoDialogDescription,
    KoButton,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { "[attr.title]": "null", class: "contents" },
  template: `
    <ko-dialog [open]="open()" [disableClose]="pending()" (openChange)="open.set($event)">
      <ng-template koDialogContent>
        <ko-dialog-header>
          <ko-dialog-title>{{ title() }}</ko-dialog-title>
          <ko-dialog-description>{{ description() }}</ko-dialog-description>
        </ko-dialog-header>
        <ng-content />
        <div class="flex justify-end gap-2">
          <button
            koButton
            type="button"
            variant="ghost"
            [disabled]="pending()"
            (click)="open.set(false)"
          >
            {{ cancelLabel() }}
          </button>
          <button
            koButton
            type="button"
            [icon]="destructive() ? alert : check"
            [loading]="pending()"
            [variant]="destructive() ? 'destructive' : 'default'"
            [disabled]="pending()"
            (click)="confirm.emit()"
          >
            {{ confirmLabel() }}
          </button>
        </div>
      </ng-template>
    </ko-dialog>
  `,
})
export class KoConfirmDialog {
  readonly open = model(false);
  readonly title = input.required<string>();
  readonly description = input.required<string>();
  readonly confirmLabel = input("Confirm");
  readonly cancelLabel = input("Cancel");
  readonly destructive = input(false, { transform: booleanAttribute });
  readonly pending = input(false, { transform: booleanAttribute });
  readonly confirm = output<void>();

  protected readonly alert = lucideTriangleAlert;
  protected readonly check = lucideCheck;
}

import {
  ChangeDetectionStrategy,
  Component,
  provideZonelessChangeDetection,
  signal,
} from "@angular/core";
import { TestBed, type ComponentFixture } from "@angular/core/testing";
import { KoConfirmDialog } from "@/ui/confirm-dialog.component";

@Component({
  selector: "ko-confirm-host",
  imports: [KoConfirmDialog],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <ko-confirm-dialog
      title="Delete 2 items?"
      description="This cannot be undone."
      confirmLabel="Delete"
      [destructive]="destructive()"
      [pending]="pending()"
      [(open)]="open"
      (confirm)="confirmed.set(confirmed() + 1)"
    >
      <p id="extra">Extra body</p>
    </ko-confirm-dialog>
  `,
})
class HostComponent {
  readonly open = signal(false);
  readonly pending = signal(false);
  readonly destructive = signal(false);
  readonly confirmed = signal(0);
}

describe("KoConfirmDialog", () => {
  let fixture: ComponentFixture<HostComponent>;
  let host: HostComponent;

  const settle = async () => {
    fixture.detectChanges();
    await fixture.whenStable();
    await new Promise((resolve) => setTimeout(resolve, 0));
    fixture.detectChanges();
    await fixture.whenStable();
  };
  const exited = async () => {
    await new Promise((resolve) => setTimeout(resolve, 400));
    await settle();
  };
  const buttons = () =>
    Array.from(document.querySelectorAll<HTMLButtonElement>('[role="dialog"] button'));
  const button = (text: string) => buttons().find((node) => node.textContent?.trim() === text)!;

  beforeEach(async () => {
    TestBed.configureTestingModule({ providers: [provideZonelessChangeDetection()] });
    fixture = TestBed.createComponent(HostComponent);
    host = fixture.componentInstance;
    document.body.appendChild(fixture.nativeElement);
    host.open.set(true);
    await settle();
  });

  afterEach(() => {
    fixture.destroy();
    document.querySelectorAll(".cdk-overlay-container").forEach((node) => node.replaceChildren());
  });

  it("shows the title, description and projected body", () => {
    const panel = document.querySelector('[role="dialog"]')!;
    expect(panel.textContent).toContain("Delete 2 items?");
    expect(panel.textContent).toContain("This cannot be undone.");
    expect(panel.querySelector("#extra")).not.toBeNull();
  });

  it("emits confirm once when the confirm button is clicked", async () => {
    button("Delete").click();
    await settle();
    expect(host.confirmed()).toBe(1);
    expect(host.open()).toBe(true);
  });

  it("sets open to false on cancel", async () => {
    button("Cancel").click();
    await settle();
    await exited();
    expect(host.open()).toBe(false);
    expect(document.querySelector('[role="dialog"]')).toBeNull();
  });

  it("disables confirm and marks it busy when pending changes while open", async () => {
    expect(button("Delete").disabled).toBe(false);
    host.pending.set(true);
    await fixture.whenStable();
    expect(button("Delete").disabled).toBe(true);
    expect(button("Delete").getAttribute("aria-busy")).toBe("true");
    expect(button("Cancel").disabled).toBe(true);
  });

  it("stays open on Escape while pending and closes on Escape once it is not", async () => {
    const escape = () =>
      document
        .querySelector('[role="dialog"]')!
        .dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", keyCode: 27, bubbles: true }));
    host.pending.set(true);
    await fixture.whenStable();
    escape();
    await settle();
    expect(host.open()).toBe(true);
    expect(document.querySelector('[role="dialog"]')).not.toBeNull();

    host.pending.set(false);
    await fixture.whenStable();
    escape();
    await settle();
    await exited();
    expect(host.open()).toBe(false);
    expect(document.querySelector('[role="dialog"]')).toBeNull();
  });

  it("uses the destructive variant when destructive", async () => {
    expect(button("Delete").className).not.toContain("bg-destructive");
    host.destructive.set(true);
    await fixture.whenStable();
    expect(button("Delete").className).toContain("bg-destructive");
  });
});
